import sys

def max_expression_value(s):
    def evaluate(expression):
        stack = []
        i = 0
        while i < len(expression):
            if expression[i].isdigit():
                num = int(expression[i])
                i += 1
                while i < len(expression) and expression[i].isdigit():
                    num = num * 10 + int(expression[i])
                    i += 1
                stack.append(num)
            elif expression[i] == '+':
                i += 1
                num = int(expression[i])
                i += 1
                while i < len(expression) and expression[i].isdigit():
                    num = num * 10 + int(expression[i])
                    i += 1
                stack.append(num)
            elif expression[i] == '*':
                i += 1
                num = int(expression[i])
                i += 1
                while i < len(expression) and expression[i].isdigit():
                    num = num * 10 + int(expression[i])
                    i += 1
                stack[-1] *= num
        return sum(stack)

    max_value = float('-inf')
    for i in range(1, len(s), 2):
        left = s[:i]
        right = s[i+1:]
        value = evaluate(left) + evaluate(right)
        if '*' in s[:i]:
            value = evaluate(left[:i-1]) * evaluate(left[i:]) + evaluate(right)
        if '*' in s[i+1:]:
            value = evaluate(left) + evaluate(right[:i]) * evaluate(right[i+1:])
        if value > max_value:
            max_value = value

    return max_value

if __name__ == "__main__":
    s = input().strip()
    print(max_expression_value(s))
